ALTER TABLE applications MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE application_menu_drafts MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE application_menu_releases MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE application_menu_release_items MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE tenant_application_grants MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
ALTER TABLE application_outbox_events MODIFY COLUMN created_at TIMESTAMP(6) NOT NULL, MODIFY COLUMN updated_at TIMESTAMP(6) NOT NULL, ADD COLUMN deleted_at TIMESTAMP(6) NULL, ADD COLUMN deleted_by TEXT NULL;
UPDATE application_menu_drafts SET deleted_at=updated_at,deleted_by=updated_by WHERE status='deleted';
CREATE TRIGGER applications_audit_bi BEFORE INSERT ON applications FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_at=NULL,NEW.deleted_by=NULL;
CREATE TRIGGER applications_audit_bu BEFORE UPDATE ON applications FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER applications_audit_bd BEFORE DELETE ON applications FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
